$ErrorActionPreference='Stop';if(-not$IsWindows){throw 'Filesystem ACL governance requires Windows'}
$fixture=Join-Path ([IO.Path]::GetTempPath()) ('et-acl-governance-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory $fixture|Out-Null
try{
    $service=[Security.Principal.SecurityIdentifier]::new('S-1-5-80-100-200-300-400-500');$current=[Security.Principal.WindowsIdentity]::GetCurrent().User;$system=[Security.Principal.SecurityIdentifier]::new('S-1-5-18');$admins=[Security.Principal.SecurityIdentifier]::new('S-1-5-32-544');$everyone=[Security.Principal.SecurityIdentifier]::new('S-1-1-0');$users=[Security.Principal.SecurityIdentifier]::new('S-1-5-32-545')
    function Set-DirectoryPolicy([string]$Path,[Security.AccessControl.FileSystemRights]$ServiceRights,[Security.Principal.SecurityIdentifier]$ExtraSid=$null,[Security.AccessControl.FileSystemRights]$ExtraRights=0){$acl=[Security.AccessControl.DirectorySecurity]::new();$acl.SetAccessRuleProtection($true,$false);$entries=@(@($current,[Security.AccessControl.FileSystemRights]::FullControl),@($system,[Security.AccessControl.FileSystemRights]::FullControl),@($admins,[Security.AccessControl.FileSystemRights]::FullControl),@($service,$ServiceRights));if($ExtraSid){$entries+=,@($ExtraSid,$ExtraRights)};foreach($entry in $entries){$acl.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new($entry[0],$entry[1],[Security.AccessControl.InheritanceFlags]'ContainerInherit, ObjectInherit',[Security.AccessControl.PropagationFlags]::None,[Security.AccessControl.AccessControlType]::Allow))};Set-Acl -LiteralPath $Path -AclObject $acl}
    function Set-FilePolicy([string]$Path,[Security.AccessControl.FileSystemRights]$ServiceRights){$acl=[Security.AccessControl.FileSecurity]::new();$acl.SetAccessRuleProtection($true,$false);foreach($entry in @(@($current,[Security.AccessControl.FileSystemRights]::FullControl),@($system,[Security.AccessControl.FileSystemRights]::FullControl),@($admins,[Security.AccessControl.FileSystemRights]::FullControl),@($service,$ServiceRights))){$acl.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new($entry[0],$entry[1],[Security.AccessControl.AccessControlType]::Allow))};Set-Acl -LiteralPath $Path -AclObject $acl}
    function New-Case([string]$Name,[string]$Unsafe){$root=Join-Path $fixture $Name;$release=Join-Path $root 'releases';$runtime=Join-Path $root 'runtime';$state=Join-Path $root 'state';$secret=Join-Path $root 'secrets';New-Item -ItemType Directory $release,$runtime,$state,$secret -Force|Out-Null;$key=Join-Path $secret 'state.private.pem';[IO.File]::WriteAllText($key,'TEST-ONLY-NOT-A-KEY')
        $releaseExtra=$(if($Unsafe-eq'broad-release-write'){$everyone}else{$null});$releaseExtraRights=$(if($releaseExtra){[Security.AccessControl.FileSystemRights]::Write}else{0});Set-DirectoryPolicy $release ([Security.AccessControl.FileSystemRights]::ReadAndExecute) $releaseExtra $releaseExtraRights
        Set-DirectoryPolicy $runtime ([Security.AccessControl.FileSystemRights]::Modify);Set-DirectoryPolicy $state $(if($Unsafe-eq'state-readonly'){[Security.AccessControl.FileSystemRights]::Read}else{[Security.AccessControl.FileSystemRights]::Modify})
        $secretRights=$(if($Unsafe-eq'service-secret-write'){[Security.AccessControl.FileSystemRights]::Modify}else{[Security.AccessControl.FileSystemRights]::Read});$secretExtra=$(if($Unsafe-eq'broad-secret-read'){$users}else{$null});$secretExtraRights=$(if($secretExtra){[Security.AccessControl.FileSystemRights]::Read}else{0});Set-DirectoryPolicy $secret $secretRights $secretExtra $secretExtraRights;Set-FilePolicy $key $secretRights
        return @{ReleaseRoot=$release;RuntimeRoot=$runtime;DeploymentStateRoot=$state;SecretRoot=$secret;ServiceIdentity=$service.Value;PrivateKeyFiles=@($key)}
    }
    $valid=New-Case 'valid' '';$result=(((& "$PSScriptRoot/Test-ServerFilesystemAcl.ps1" @valid)-join[Environment]::NewLine)|ConvertFrom-Json);if(-not$result.Passed){throw 'Valid filesystem ACL policy failed'}
    foreach($case in @('broad-release-write','broad-secret-read','service-secret-write','state-readonly')){$p=New-Case $case $case;$rejected=$false;try{& "$PSScriptRoot/Test-ServerFilesystemAcl.ps1" @p|Out-Null}catch{$rejected=$true};if(-not$rejected){throw "Unsafe filesystem ACL case was accepted: $case"}}
    [ordered]@{Passed=$true;RealWindowsAclInspected=$true;DedicatedServiceIdentityVerified=$true;BroadReleaseWriteRejected=$true;BroadSecretReadRejected=$true;ServiceSecretWriteRejected=$true;MissingStateWriteRejected=$true}|ConvertTo-Json
}finally{$temp=[IO.Path]::GetFullPath([IO.Path]::GetTempPath()).TrimEnd('\','/')+[IO.Path]::DirectorySeparatorChar;$resolved=[IO.Path]::GetFullPath($fixture);if($resolved.StartsWith($temp,[StringComparison]::OrdinalIgnoreCase)-and[IO.Path]::GetFileName($resolved)-match'^et-acl-governance-[a-f0-9]{32}$'-and(Test-Path $resolved)){Remove-Item $resolved -Recurse -Force}}
